**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    vector<int> d(n - 1);
    for (int i = 0; i < n - 1; i++)
        d[i] = T[i + 1] - T[i];

    int maxDl = 2, maxStart = 0;
    int curDl = 2, curStart = 0;

    for (int i = 1; i < (int)d.size(); i++) {
        if ((long long)d[i] * d[i - 1] < 0) {
            curDl++;
        } else {
            if (curDl > maxDl) { maxDl = curDl; maxStart = curStart; }
            curDl = 2; curStart = i;
        }
    }
    if (curDl > maxDl) { maxDl = curDl; maxStart = curStart; }

    cout << "Najdluzszy ciag naprzemienny:" << endl;
    cout << "Dlugosc: " << maxDl << ", pozycja poczatkowa: " << maxStart + 1 << endl;
    cout << "Elementy:";
    for (int i = maxStart; i < maxStart + maxDl; i++)
        cout << " " << T[i];
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Obliczamy roznice sasiadow, potem szukamy najdluzszego ciagu naprzemiennych znakow (iloczyn sasiadnich roznic < 0). Dlugosc elementow = dlugosc pasujacych roznic + 1.

